const raw=$('DB | Load Salesforce Sync Context').item.json.sync_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;
if(!ctx||ctx.connector_key!=='salesforce_primary') throw new Error('SALESFORCE_SYNC_CONTEXT_INVALID');
let gate=ctx.reliability_gate;if(typeof gate==='string')gate=JSON.parse(gate);
const allowed=gate?.allowed===true;
return {sync_context:ctx,should_sync:allowed,skip_reason:allowed?null:(gate?.reason??'CONNECTOR_NOT_READY')};

const raw=$('DB | Load Salesforce Sync Context').first().json.sync_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;
const rows=$input.all().map(x=>x.json??{});
if(rows.length>10000) throw new Error('SALESFORCE_SYNC_RESULT_LIMIT_EXCEEDED');
const expected=String(ctx.currency_code??'').trim().toUpperCase();
const start=new Date(ctx.query_start_at).getTime(),end=new Date(ctx.query_end_at).getTime();
const records=[];let rejected=0,earliest=null;
const iso=v=>{if(v===null||v===undefined||v==='')return null;const d=new Date(v);return Number.isNaN(d.getTime())?null:d.toISOString();};
for(const r of rows){
 const id=String(r.Id??r.id??'').trim();const amount=Number(r.Amount??0);
 const currency=String(r.CurrencyIsoCode??expected).trim().toUpperCase();
 const stage=String(r.StageName??'').trim();const updated=iso(r.LastModifiedDate);
 if(updated){const ms=new Date(updated).getTime();if(ms<start||ms>end)continue;}
 const close=iso(r.CloseDate),created=iso(r.CreatedDate);
 const won=r.IsWon===true||String(r.IsWon).toLowerCase()==='true'||stage.toLowerCase()==='closed won';
 const closed=r.IsClosed===true||String(r.IsClosed).toLowerCase()==='true'||/^closed\b/i.test(stage);
 const cat=won?'won':(closed?'lost':'open');
 const valid=id&&Number.isFinite(amount)&&amount>=0&&currency===expected&&stage&&(cat==='open'||close);
 if(!valid){rejected++;const ms=updated?new Date(updated).getTime():null;if(ms!==null&&(earliest===null||ms<earliest))earliest=ms;continue;}
 records.push({source_record_id:id,source_payload:{Name:r.Name??null,Amount:String(amount),CurrencyIsoCode:currency,
  StageName:stage,OwnerId:r.OwnerId??null,LeadSource:r.LeadSource??null,CreatedDate:created,CloseDate:close,
  LastModifiedDate:updated,revint_stage_category:cat}});
}
let wm=end;if(rejected>0)wm=earliest===null?start:Math.max(start,earliest);
return [{json:{connector_key:'salesforce_primary',query_start_at:new Date(start).toISOString(),
 query_end_at:new Date(end).toISOString(),watermark:new Date(wm).toISOString(),source_count:rows.length,
 record_count:records.length,rejected_count:rejected,records,event_id:'SALESFORCE-SYNC-'+String(end)}}];
